// Bundles server/tutor/entry.ts into api/hint.js so Vercel can run it without resolving imports.
// Usage: node scripts/build-api.mjs [--check]   (--check fails if api/hint.js is out of date)
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { build } from 'esbuild'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const outfile = resolve(root, 'api/hint.js')
const banner =
  '// GENERATED by `npm run build:api` from server/tutor/entry.ts. Do not edit by hand.\n' +
  '// Self-contained on purpose: Vercel runs api/ unbundled, where extensionless relative imports do not resolve.'

export async function bundleHint() {
  const result = await build({
    entryPoints: [resolve(root, 'server/tutor/entry.ts')],
    bundle: true,
    platform: 'node',
    format: 'esm',
    target: 'node20',
    minify: true,
    legalComments: 'none',
    banner: { js: banner },
    write: false,
    logLevel: 'warning',
  })
  return result.outputFiles[0].text
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const text = await bundleHint()
  if (process.argv.includes('--check')) {
    let current = ''
    try {
      current = readFileSync(outfile, 'utf8')
    } catch {
      // a missing file counts as out of date
    }
    if (current !== text) {
      console.error('api/hint.js is out of date. Run `npm run build:api` and commit the result.')
      process.exit(1)
    }
  } else {
    mkdirSync(dirname(outfile), { recursive: true })
    writeFileSync(outfile, text)
    console.log(`api/hint.js ${(text.length / 1024).toFixed(1)} kB`)
  }
}
